// Browser-local viewing history. Never store tokens or private programme data.
const progressMemory=new Map();
function progressKey(){return 'otv-watch-v1:'+String(user?.id||'guest')}
function readProgress(key=progressKey()){
 if(progressMemory.has(key))return progressMemory.get(key);
 try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value.filter(p=>p&&typeof p.id==='string'&&/^[\w-]{11}$/.test(p.video||'')&&Number.isFinite(p.seconds)&&p.seconds>=0&&Number.isFinite(p.duration)&&p.duration>0&&Number.isFinite(p.updated)).slice(0,100):[]}catch{return progressMemory.get(key)||[]}
}
function writeProgress(rows,key=progressKey()){try{localStorage.setItem(key,JSON.stringify(rows));progressMemory.delete(key)}catch{progressMemory.set(key,rows)}}
function forgetProgress(id,key=progressKey()){writeProgress(readProgress(key).filter(p=>p.id!==id),key)}
function saveProgress(id,video,seconds,duration,ended=false,key=progressKey()){
 if(!Number.isFinite(seconds)||!Number.isFinite(duration)||duration<=0)return;
 if(ended||seconds>=duration-10){forgetProgress(id,key);return}
 if(seconds<10)return;
 writeProgress([{id,video,seconds:Math.floor(seconds),duration,updated:Date.now()},...readProgress(key).filter(p=>p.id!==id)].slice(0,100),key);
}
function episodeProgress(ep){return readProgress().find(p=>p.id===ep.id&&p.video===youtube(ep.youtube_url)&&p.seconds<p.duration-10)}
function clockTime(s){s=Math.max(0,Math.floor(s));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}
function continueWatching(){
 const episodes=published(data.episodes).filter(e=>published(data.programmes).some(p=>p.id===e.programme_id));const rows=readProgress().sort((a,b)=>b.updated-a.updated).map(p=>({p,ep:episodes.find(e=>e.id===p.id&&youtube(e.youtube_url)===p.video)})).filter(x=>x.ep&&x.p.seconds>=10&&x.p.seconds<x.p.duration-10).slice(0,6);
 if(!rows.length)return '';
 return `<section class="section continue-section"><div class="section-head"><h2>Continue watching</h2><button class="quiet-button" type="button" data-clear-progress>Clear history</button></div><p class="muted watch-local-note">Saved in this browser${user?' for your account':''}.</p><div class="grid episode-rail">${rows.map(({p,ep})=>`<div class="resume-card"><a class="card" href="#episode/${esc(ep.id)}">${art(ep.thumbnail)}<progress max="${p.duration}" value="${p.seconds}" aria-label="Viewing progress for ${esc(ep.title)}"></progress><h3>${esc(ep.title)}</h3><p>Resume from ${clockTime(p.seconds)}</p></a><button type="button" class="quiet-button" data-remove-progress="${esc(ep.id)}" aria-label="Remove ${esc(ep.title)} from continue watching">Remove</button></div>`).join('')}</div></section>`;
}
let youtubeApiPromise=null,watchSession=null,watchGeneration=0;
function loadYoutubeAPI(){
 if(window.YT?.Player)return Promise.resolve(window.YT);
 if(youtubeApiPromise)return youtubeApiPromise;
 youtubeApiPromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.async=true;
  const timeout=setTimeout(()=>{youtubeApiPromise=null;script.remove();reject(Error('Player connection timed out'))},15000);
  window.onYouTubeIframeAPIReady=()=>{clearTimeout(timeout);resolve(window.YT)};
  script.onerror=()=>{clearTimeout(timeout);youtubeApiPromise=null;script.remove();reject(Error('Player connection unavailable'))};document.head.append(script);
 });return youtubeApiPromise;
}
function persistWatch(){const s=watchSession;if(!s?.ready||s.ended)return;try{saveProgress(s.id,s.video,s.player.getCurrentTime(),s.player.getDuration(),false,s.key)}catch{}}
function stopWatch(){watchGeneration++;persistWatch();if(watchSession){clearInterval(watchSession.timer);try{watchSession.player.destroy()}catch{}watchSession=null}}
async function connectWatch(){
 const iframe=document.querySelector('#episode-player');if(!iframe)return;
 const generation=watchGeneration,id=iframe.dataset.episode,video=iframe.dataset.video;
 try{const YT=await loadYoutubeAPI();if(generation!==watchGeneration||!iframe.isConnected)return;
  const s={id,video,key:progressKey(),player:null,ready:false,ended:false,timer:null};watchSession=s;
  s.player=new YT.Player(iframe,{events:{onReady:()=>{
   if(watchSession!==s)return;s.ready=true;
   const restart=document.querySelector('#restart-episode');if(restart){restart.disabled=false;restart.onclick=()=>{forgetProgress(id,s.key);s.ended=false;s.player.seekTo(0,true);document.querySelector('#resume-label').textContent='Starting from the beginning.'}};
   s.timer=setInterval(()=>{if(watchSession===s&&s.player.getPlayerState()===1)persistWatch()},5000);
  },onStateChange:e=>{if(watchSession!==s)return;if(e.data===0){s.ended=true;forgetProgress(id,s.key)}else if(e.data===1){s.ended=false}else if(e.data===2)persistWatch()},onError:()=>{const note=document.querySelector('#resume-label');if(note)note.textContent='Playback is unavailable here. You can try the YouTube link below.'}}});
 }catch{const note=document.querySelector('#resume-label');if(note)note.textContent='Video controls are available, but viewing progress could not connect.'}
}
window.addEventListener('pagehide',persistWatch);document.addEventListener('visibilitychange',()=>{if(document.hidden)persistWatch()});
function enhancedPlayer(x,track=false){
 const id=youtube(x.youtube_url);if(!id)return empty('No video available','This programme does not have a playable video yet.');
 const saved=track?episodeProgress(x):null;const params=new URLSearchParams({origin:location.origin,playsinline:'1',rel:'0'});if(track)params.set('enablejsapi','1');if(saved)params.set('start',String(Math.floor(saved.seconds)));
 return `<div class="player"><iframe ${track?`id="episode-player" data-episode="${esc(x.id)}" data-video="${id}"`:''} src="https://www.youtube-nocookie.com/embed/${id}?${esc(params.toString())}" title="${esc(x.title)}" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div>${track?`<div class="watch-tools"><p id="resume-label" class="muted">${saved?'Resume from '+clockTime(saved.seconds)+'.':'Progress saves as you watch.'} Saved in this browser.</p><button type="button" id="restart-episode" disabled>Start again</button></div>`:''}<p class="muted">If playback is unavailable, <a href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">watch on YouTube ↗</a>.</p>`;
}
function searchMatches(query){const q=query.trim().toLowerCase();if(!q)return [];return [['programmes','show','Show'],['episodes','episode','Episode'],['articles','article','News']].flatMap(([table,type,label])=>published(data[table]).filter(x=>table!=='episodes'||published(data.programmes).some(p=>p.id===x.programme_id)).filter(x=>`${x.title} ${x.description||''} ${x.tags||''}`.toLowerCase().includes(q)).map(x=>({...x,type,label}))).sort((a,b)=>Number(b.title.toLowerCase().startsWith(q))-Number(a.title.toLowerCase().startsWith(q))).slice(0,7)}
function setupSearchSuggestions(){
 const form=$('#search'),input=form.querySelector('input');const box=document.createElement('div');box.id='search-suggestions';box.className='search-suggestions';box.hidden=true;box.setAttribute('aria-label','Search suggestions');form.append(box);
 input.setAttribute('aria-controls',box.id);input.setAttribute('aria-expanded','false');input.autocomplete='off';
 const close=()=>{box.hidden=true;input.setAttribute('aria-expanded','false')};
 const update=()=>{const q=input.value.trim();if(!q){close();return}const matches=searchMatches(q);box.innerHTML=`<p class="suggestion-heading">${matches.length?'Suggestions':'No matches yet'}</p>${matches.map(x=>`<a href="#${x.type}/${esc(x.id)}"><span>${esc(x.title)}</span><small>${x.label}</small></a>`).join('')}<a class="search-all" href="#search/${encodeURIComponent(q)}">Search all results →</a>`;box.hidden=false;input.setAttribute('aria-expanded','true')};
 input.addEventListener('input',update);input.addEventListener('focus',update);
 form.addEventListener('keydown',e=>{if(e.key==='Escape'){input.focus();close();return}if(!['ArrowDown','ArrowUp'].includes(e.key))return;if(box.hidden)update();const links=[...box.querySelectorAll('a')];if(!links.length)return;e.preventDefault();const index=links.indexOf(document.activeElement);links[(index+(e.key==='ArrowDown'?1:-1)+links.length)%links.length].focus()});
 form.addEventListener('focusout',()=>setTimeout(()=>{if(!form.contains(document.activeElement))close()},0));document.addEventListener('click',e=>{if(!form.contains(e.target))close()});form.addEventListener('submit',close);window.addEventListener('hashchange',close);
}
function richerCards(rows,type){return `<div class="grid ${type==='episode'?'episode-rail':''}">${rows.map(x=>`<a class="card rich-card" href="#${type}/${esc(x.id)}">${art(x.thumbnail)}<div class="card-copy"><h3>${esc(x.title)}</h3><p>${esc(x.category||x.description?.slice(0,65)||'')}</p></div><div class="card-reveal"><p>${esc(x.description||'')}</p><span>${type==='show'?'Explore show':type==='episode'?'Watch episode':'Read story'} <span aria-hidden="true">→</span></span></div></a>`).join('')}</div>`}
function showAccent(show){return /^#[\da-f]{6}$/i.test(show?.accent_color||'')?show.accent_color:'#d2c1ed'}
function livePage(){
 const now=Date.now(),rows=published(data.broadcasts).filter(x=>x.broadcast_status!=='cancelled');const live=rows.find(x=>x.broadcast_status==='live');const upcoming=rows.filter(x=>x.broadcast_status==='scheduled'&&new Date(x.starts_at)>now).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));const next=upcoming[0];
 return `<div class="page-top"><span class="eyebrow">OTV Live</span><h1>${esc(live?.title||'The home of live OTV.')}</h1><p class="muted">${esc(live?.description||'When we’re on air, you’ll find us here.')}</p></div><div class="live-layout"><section aria-label="Live player">${live?player(live):'<div class="player"><div><span class="badge">Off air</span><h2 class="section">We’ll be back soon.</h2><p class="muted">There’s no active broadcast right now.</p><a class="button" href="#shows">Explore our shows →</a></div></div>'}<div class="live-now-strip"><span class="badge ${live?'red':''}">${live?'On now':'Off air'}</span><strong>${esc(live?.title||'No current broadcast')}</strong>${live?`<span class="muted">${time(live.starts_at)}–${time(live.ends_at)}</span>`:''}</div></section><aside class="live-lineup panel"><div class="section-head"><h2>Up next</h2><a href="#schedule">Full schedule →</a></div>${next?`<p class="eyebrow">${stamp(next.starts_at)} · ${time(next.starts_at)}</p><h3>${esc(next.title)}</h3><p class="muted">${esc(next.description||'')}</p>`:'<p class="muted">The next broadcast hasn’t been scheduled yet.</p>'}<h2 class="section">Coming up</h2>${schedule(upcoming.slice(1,5))}<p class="watch-local-note muted">Times in ${esc(settings.timezone||'Europe/London')}.</p><button type="button" id="refresh-live">Refresh line-up</button></aside></div>`;
}
// Image state is progressive enhancement: images remain visible without JavaScript.
function enhanceImages(root){root.querySelectorAll('.art img,.programme-backdrop img').forEach(img=>{if(img.dataset.imageBound)return;img.dataset.imageBound='1';const frame=img.parentElement;const done=()=>{img.classList.remove('image-pending');frame.classList.remove('image-loading');if(!img.naturalWidth){frame.classList.add('image-unavailable');img.hidden=true;frame.setAttribute('aria-label','Artwork unavailable')}else img.classList.add('image-ready')};if(img.complete){done();return}img.classList.add('image-pending');frame.classList.add('image-loading');img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true})})}
function setupImageObserver(){const observer=new MutationObserver(entries=>{for(const e of entries)for(const node of e.addedNodes)if(node.nodeType===1){enhanceImages(node);if(node.matches?.('img'))enhanceImages(node.parentElement)}});for(const el of [$('#main'),$('#dialog-body')])observer.observe(el,{childList:true,subtree:true});enhanceImages(document)}
function previewDocument(show,episodes,sections,key){
 const markup=showHubPage(show,episodes,sections,key),css=new URL('style.css',location.href).href,logo=new URL('otv-logo.png',location.href).href;
 return `<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="${esc(css)}"><style>body{overflow-x:hidden}#intro{display:none}a,button{pointer-events:none}header #nav{overflow-x:auto}.preview-static{font-size:11px;color:#b8bec4}</style></head><body><header><a class="logo"><img src="${esc(logo)}" alt="OTV"></a><nav id="nav">${['Home','Shows','Live','News','Schedule','About','Status'].map(t=>`<a>${t}</a>`).join('')}</nav></header><main class="programme-page" style="--show-accent:${showAccent(show)}">${markup}</main></body></html>`;
}
function mountHubPreview(area,show,episodes,sections,selected='home'){
 area.hidden=false;area.innerHTML=`<p class="hub-preview-label">DRAFT PREVIEW · NOT PUBLISHED</p><div class="preview-toolbar"><button type="button" data-preview-size="desktop" aria-pressed="true">Desktop</button><button type="button" data-preview-size="phone" aria-pressed="false">Phone</button><label>Preview section<select data-preview-section>${sections.filter(s=>!s.hidden).map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select></label></div><div class="preview-frame-wrap"><iframe class="hub-preview-frame" title="Show page preview" sandbox="" loading="lazy"></iframe></div><p class="muted preview-note">Preview only. Links and playback are disabled. Save or publish when you’re ready.</p>`;
 const select=area.querySelector('select');select.value=sections.some(s=>s.id===selected&&!s.hidden)?selected:'home';const frame=area.querySelector('iframe');const draw=()=>frame.srcdoc=previewDocument(show,episodes,sections,select.value);select.onchange=draw;
 area.querySelectorAll('[data-preview-size]').forEach(b=>b.onclick=()=>{frame.classList.toggle('phone-preview',b.dataset.previewSize==='phone');area.querySelectorAll('[data-preview-size]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});draw();
}
function setupShowEditorPreview(form,row){
 const details=document.createElement('details');details.className='editor-preview';details.innerHTML='<summary>Preview banner and show page</summary><div class="editor-preview-content"></div>';form.querySelector('.editor-grid').after(details);
 let timer;const update=()=>{if(!details.open)return;const values=Object.fromEntries(new FormData(form));const show={...row,...values,id:row.id||'preview'};const episodes=published(data.episodes).filter(e=>e.programme_id===row.id).sort((a,b)=>new Date(b.publish_at)-new Date(a.publish_at));const sections=(data.show_hub_published||[]).find(h=>h.programme_id===row.id)?.sections||defaultHubSections();mountHubPreview(details.querySelector('.editor-preview-content'),show,episodes,sections)};
 details.addEventListener('toggle',update);form.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(update,250)});
}
function enhancePage(){
 const route=location.hash.slice(1).split('/');const show=route[0]==='show'?published(data.programmes).find(x=>x.id===route[1]):null;$('#main').style.setProperty('--show-accent',showAccent(show));
 document.querySelectorAll('[data-remove-progress]').forEach(b=>b.onclick=()=>{forgetProgress(b.dataset.removeProgress);render()});document.querySelectorAll('[data-clear-progress]').forEach(b=>b.onclick=()=>{writeProgress([]);render()});
 const refresh=$('#refresh-live');if(refresh)refresh.onclick=async()=>{refresh.disabled=true;refresh.textContent='Refreshing…';await refreshLiveLineup()};
 enhanceImages($('#main'));connectWatch();
}
async function refreshLiveLineup(){await refresh();await render()}

// Animate navigation once; background content refreshes never replay entrances.
let motionRoute = null, motionObserver = null;
const motionPreference = window.matchMedia?.('(prefers-reduced-motion: reduce)');
const activeMotion = new Set();
motionPreference?.addEventListener('change', () => {
 if(motionPreference.matches){motionObserver?.disconnect();activeMotion.forEach(a=>a.cancel());activeMotion.clear()}
});
function animatePage(root){
 motionObserver?.disconnect();
 const route=location.hash||'#home';
 if(motionRoute===route)return;
 motionRoute=route;
 activeMotion.forEach(a=>a.cancel());activeMotion.clear();
 if(motionPreference?.matches||!Element.prototype.animate)return;
 const enter=(el,delay=0)=>{
  const animation=el.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:460,delay,easing:'cubic-bezier(.2,.7,.2,1)',fill:'backwards'});
  activeMotion.add(animation);animation.onfinish=animation.oncancel=()=>activeMotion.delete(animation);
 };
 root.querySelectorAll('.programme-hero-content > *, .show-feature-copy > *, .page-top, .service-heading, .hub-menu').forEach((el,i)=>enter(el,Math.min(i*45,225)));
 const blocks=root.querySelectorAll('.section, .broadcast-row, .hub-rail, .hub-prose, .service-summary, .service-group, .service-columns aside, .programme-about');
 if(!('IntersectionObserver' in window))return;
 motionObserver=new IntersectionObserver(entries=>{let i=0;for(const entry of entries){if(entry.isIntersecting){if(!motionPreference?.matches)enter(entry.target,Math.min(i++*50,150));motionObserver.unobserve(entry.target)}}},{threshold:.08});
 blocks.forEach(el=>motionObserver.observe(el));
}

function defaultHubSections(){return ['home','episodes','news','about'].map(kind=>({id:kind,kind,title:kind[0].toUpperCase()+kind.slice(1),hidden:false,body:'',image:''}))}
function hubSectionContent(section,show,episodes,sections){
 const articles=published(data.articles).filter(x=>x.programme_id===show.id);
 const text=section.body?`<div class="hub-prose">${esc(section.body)}</div>`:'';
 const image=safe(section.image)?`<img class="hub-content-image" src="${esc(safe(section.image))}" alt="${esc(section.title)}">`:'';
 const epCards=list=>`<div class="programme-episode-grid">${list.map(ep=>`<a class="programme-episode" href="#episode/${ep.id}"><div class="programme-episode-art">${art(ep.thumbnail)}${ep.duration?`<span class="programme-duration">${esc(ep.duration)}</span>`:''}<span class="programme-play" aria-hidden="true">▶</span></div><div class="programme-episode-meta">${[ep.season?'Series '+esc(ep.season):'',ep.episode_number?'Episode '+esc(ep.episode_number):'',stamp(ep.publish_at)].filter(Boolean).join(' · ')}</div><h3>${esc(ep.title)}</h3><p>${esc(ep.description)}</p></a>`).join('')}</div>`;
 if(section.kind==='home')return `${sections.some(s=>s.kind==='episodes')?`<section class="hub-rail"><h2>Latest episodes</h2>${episodes.length?epCards(episodes.slice(0,4)):'<p class="muted">Episodes will appear here when published.</p>'}</section>`:''}${image}${text}${sections.some(s=>s.kind==='news')&&articles.length?`<section class="hub-rail"><h2>From ${esc(show.title)}</h2>${cards(articles.slice(0,4),'article')}</section>`:''}${!text&&!episodes.length&&!articles.length?`<p class="hub-prose">${esc(show.description||'Welcome to '+show.title+'.')}</p>`:''}`;
 if(section.kind==='episodes'){const seasons=[...new Set(episodes.map(e=>e.season||0))].sort((a,b)=>b-a);return `${text}${seasons.length?seasons.map(s=>`<section class="hub-rail">${seasons.length>1?`<h3>${s?'Series '+s:'More episodes'}</h3>`:''}${epCards(episodes.filter(e=>(e.season||0)===s))}</section>`).join(''):'<p class="muted">No episodes published yet.</p>'}`}
 if(section.kind==='news')return `${text}${articles.length?cards(articles,'article'):'<p class="muted">No programme news published yet.</p>'}`;
 if(section.kind==='about')return `${image}<div class="hub-prose">${esc(section.body||show.body||show.description)}</div>${show.creator?`<p class="muted">Created by ${esc(show.creator)}</p>`:''}`;
 return `${image}${text||'<p class="muted">More coming soon.</p>'}`;
}
function showHubPage(show,episodes,override=null,selected=null){
 const release=(data.show_hub_published||[]).find(h=>h.programme_id===show.id);
 const source=override||release?.sections||defaultHubSections();
 const all=source.filter(s=>!s.hidden);
 const articles=published(data.articles).filter(x=>x.programme_id===show.id);
 const sections=all.filter(s=>s.kind==='home'||s.body||safe(s.image)||(s.kind==='episodes'&&episodes.length)||(s.kind==='news'&&articles.length)||(s.kind==='about'&&(show.body||show.description)));
 const key=selected||location.hash.split('/')[2]||'home';
 const current=sections.find(s=>s.id===key);
 const base=programmePage(show,episodes);const hero=base.slice(0,base.indexOf('<div class="programme-body">'));
 return `${hero}<div class="programme-body hub-body"><nav class="hub-menu" aria-label="${esc(show.title)} sections">${sections.map(s=>`<a href="#show/${show.id}/${s.id}" ${s.id===key?'aria-current="page"':''}>${esc(s.title)}</a>`).join('')}</nav><section class="hub-section">${current?`${current.kind!=='home'?`<div class="hub-section-heading"><span class="eyebrow">${esc(show.title)}</span><h2>${esc(current.title)}</h2></div>`:''}${hubSectionContent(current,show,episodes,sections)}`:`<h2>This section isn’t available.</h2><a class="button" href="#show/${show.id}/home">Back to the show</a>`}</section></div>`;
}
async function openShowHubBuilder(show){
 if(!show||!db)return;
 const dialog=$('#dialog'),body=$('#dialog-body');
 const {data:row,error}=await db.from('show_hub_drafts').select('*').eq('programme_id',show.id).maybeSingle();
 if(error){notify('Could not open the page builder. '+error.message);return;}
 let sections=structuredClone(row?.sections||defaultHubSections()),revision=row?.revision||0,chosen='home',dirty=false,busy=false;
 const canPublish=role==='admin'||permissions.publish;
 const episodes=published(data.episodes).filter(e=>e.programme_id===show.id).sort((a,b)=>new Date(b.publish_at)-new Date(a.publish_at));
 function readFields(){const s=sections.find(s=>s.id===chosen);if(!s)return;const f=body.querySelector('#hub-edit');if(f){s.title=f.elements.title.value.trim();s.body=f.elements.body.value;s.image=f.elements.image.value.trim()}}
 function draw(){const s=sections.find(s=>s.id===chosen);body.innerHTML=`<div class="hub-builder-head"><span class="eyebrow">Show page builder</span><h2>${esc(show.title)}</h2><p class="muted">Each show has its own menu. Hidden sections stay in your draft.</p></div><div class="hub-builder-grid"><aside><div class="hub-section-list">${sections.map((x,i)=>`<div class="hub-builder-row"><button type="button" data-hub-select="${x.id}" class="${x.id===chosen?'selected':''}">${esc(x.title||'Untitled')}<small>${x.hidden?'Hidden':x.kind}</small></button>${i?`<div class="hub-row-tools"><button type="button" data-hub-up="${x.id}" aria-label="Move ${esc(x.title)} up" ${i===1?'disabled':''}>↑</button><button type="button" data-hub-down="${x.id}" aria-label="Move ${esc(x.title)} down" ${i===sections.length-1?'disabled':''}>↓</button></div>`:''}</div>`).join('')}</div><label>Add a section<select id="hub-add-type">${['episodes','news','about','recipes','team','custom'].map(k=>`<option value="${k}">${k[0].toUpperCase()+k.slice(1)}</option>`).join('')}</select></label><button type="button" id="hub-add" ${sections.length>=20?'disabled':''}>＋ Add section</button></aside><div><form id="hub-edit"><label>Menu name<input name="title" maxlength="50" required value="${esc(s.title)}"></label><label>Page text<textarea name="body" maxlength="30000" rows="9">${esc(s.body)}</textarea></label><label>Page image URL<input type="url" name="image" value="${esc(s.image)}" placeholder="https://…"></label><p class="muted">Upload images in Media Library and paste the URL here. Episodes and News pull in this show’s published content automatically.</p></form>${s.kind!=='home'?`<div class="actions"><button type="button" id="hub-hide">${s.hidden?'Show section':'Hide section'}</button><button type="button" id="hub-remove">Remove section</button></div>`:'<p class="muted">Home stays first and is always available.</p>'}</div></div><div class="hub-builder-actions"><button type="button" id="hub-preview">Preview</button><button type="button" id="hub-save">Save draft</button>${canPublish?'<button type="button" class="primary" id="hub-publish">Publish show pages</button>':'<span class="muted">Save your draft for the owner to review and publish.</span>'}</div><p id="hub-message" role="status" aria-live="polite"></p><div id="hub-preview-area" hidden></div>`;
 body.querySelector('#hub-edit').onsubmit=e=>e.preventDefault();body.querySelector('#hub-edit').oninput=()=>{dirty=true};
 body.querySelectorAll('[data-hub-select]').forEach(b=>b.onclick=()=>{readFields();chosen=b.dataset.hubSelect;draw()});
 for(const dir of ['up','down'])body.querySelectorAll('[data-hub-'+dir+']').forEach(b=>b.onclick=()=>{readFields();const i=sections.findIndex(x=>x.id===b.dataset[dir==='up'?'hubUp':'hubDown']);const j=i+(dir==='up'?-1:1);if(j<1||j>=sections.length)return;[sections[i],sections[j]]=[sections[j],sections[i]];dirty=true;draw()});
 body.querySelector('#hub-add').onclick=()=>{readFields();if(sections.length>=20)return;const kind=body.querySelector('#hub-add-type').value;const id=kind+'-'+crypto.randomUUID().slice(0,8);sections.push({id,kind,title:kind==='custom'?'New page':kind[0].toUpperCase()+kind.slice(1),hidden:false,body:'',image:''});chosen=id;dirty=true;draw()};
 if(body.querySelector('#hub-hide'))body.querySelector('#hub-hide').onclick=()=>{readFields();s.hidden=!s.hidden;dirty=true;draw()};
 if(body.querySelector('#hub-remove'))body.querySelector('#hub-remove').onclick=()=>{if(!confirm('Remove this section and its page text from the draft? The live site changes only when you publish.'))return;sections=sections.filter(x=>x.id!==s.id);chosen='home';dirty=true;draw()};
 body.querySelector('#hub-preview').onclick=()=>{readFields();mountHubPreview(body.querySelector('#hub-preview-area'),show,episodes,sections,s.hidden?'home':chosen)};
 body.querySelector('#hub-save').onclick=()=>save(false);if(body.querySelector('#hub-publish'))body.querySelector('#hub-publish').onclick=()=>save(true);
 }
 async function save(publish){if(busy)return;readFields();const message=body.querySelector('#hub-message');if(sections.some(s=>!s.title||s.title.length>50)){message.textContent='Give every section a menu name (up to 50 characters).';return}if(sections.some(s=>s.image&&!safe(s.image))){message.textContent='Use a valid HTTPS image URL.';return}busy=true;body.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);$('#close-dialog').disabled=true;message.textContent='Saving…';try{const result=await db.rpc('save_show_hub',{p_programme_id:show.id,p_sections:sections,p_revision:revision,p_publish:publish});if(result.error)throw result.error;revision=result.data;dirty=false;await refresh();message.textContent=publish?'Show pages published.':'Draft saved. The live show is unchanged.';}catch(e){message.textContent=e.message||'Could not save. Close and reopen the builder before retrying if the connection was interrupted.'}finally{busy=false;$('#close-dialog').disabled=false;body.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=false)}}
 const onCancel=e=>{if(busy||(dirty&&!confirm('Discard unsaved show-page changes?')))e.preventDefault()};
 const closeButton=$('#close-dialog'),priorClose=closeButton.onclick;closeButton.onclick=()=>{if(!busy&&(!dirty||confirm('Discard unsaved show-page changes?')))dialog.close()};
 dialog.addEventListener('cancel',onCancel);dialog.addEventListener('close',()=>{dialog.classList.remove('hub-builder-dialog');dialog.removeEventListener('cancel',onCancel);closeButton.onclick=priorClose},{once:true});
 draw();dialog.classList.add('hub-builder-dialog');dialog.showModal();
}

const statusGroups=[['website','Website & discovery'],['watching','Watching OTV'],['accounts','Accounts'],['team','Creator & owner tools']];
const statusNames={unknown:'Not checked',operational:'Operational',degraded:'Degraded',outage:'Outage',maintenance:'Maintenance'};
let statusLoadToken=0;
export function statusOverall(rows){
 if(rows.some(x=>x.status==='outage'))return 'outage';
 if(rows.some(x=>x.status==='degraded'))return 'degraded';
 if(rows.some(x=>x.status==='maintenance'))return 'maintenance';
 if(!rows.length||rows.some(x=>x.status==='unknown'))return 'unknown';
 return 'operational';
}
export function validateStatusDraft(status,reason,minutes){
 if(!['operational','degraded','outage','maintenance'].includes(status))throw Error('Choose a service status.');
 const cleanReason=String(reason||'').trim();
 if(status!=='operational'&&!cleanReason)throw Error('Please explain why this component is affected.');
 if(cleanReason.length>1200)throw Error('Keep the explanation under 1,200 characters.');
 const duration=status==='maintenance'?Number(minutes):null;
 if(status==='maintenance'&&(!Number.isInteger(duration)||duration<1||duration>43200))throw Error('Enter a maintenance duration between 1 minute and 43,200 minutes (30 days).');
 return {status,reason:cleanReason,minutes:duration};
}
function statusTime(value){return value?new Date(value).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/London'}):'Not checked yet';}
function statusBadge(value){return `<span class="service-state state-${esc(value)}"><span aria-hidden="true"></span>${esc(statusNames[value]||'Not checked')}</span>`;}
function statusMaintenance(row){if(row.status!=='maintenance')return '';const late=new Date(row.maintenance_ends_at)<=new Date();return `<p class="service-maintenance-time">Expected back: <time datetime="${esc(row.maintenance_ends_at)}">${statusTime(row.maintenance_ends_at)}</time> UK time${late?' <strong>— estimate passed; awaiting an update.</strong>':''}</p>`;}
function statusHistory(changes,rows){const byId=new Map(rows.map(x=>[x.id,x.name]));return `<section class="service-history"><h2>Recent updates</h2>${changes.length?changes.map(x=>`<div class="service-history-row"><time datetime="${esc(x.created_at)}">${statusTime(x.created_at)}</time><div><h3>${esc(byId.get(x.component_id)||x.component_id)}</h3><p>${esc(statusNames[x.previous_status]||x.previous_status)} → ${esc(statusNames[x.status]||x.status)}</p>${x.reason?`<p class="service-reason">${esc(x.reason)}</p>`:''}</div>${statusBadge(x.status)}</div>`).join(''):'<p class="muted">No status changes have been recorded yet.</p>'}</section>`;}
async function renderStatusPage(target,ownerMode=false){
 const token=++statusLoadToken;
 if(ownerMode&&role!=='admin'){target.innerHTML=empty('Owner access required','Only the OTV owner can change service status.');return;}
 target.innerHTML='<p class="muted" role="status">Loading service status…</p>';
 if(!db){target.innerHTML=empty('Service status is unavailable','We can’t load the status service right now. This does not confirm an outage.');return;}
 try{
  const [components,history]=await Promise.all([db.from('status_components').select('*').order('position'),db.from('status_changes').select('*').order('created_at',{ascending:false}).order('id',{ascending:false}).limit(12)]);
  if(components.error)throw components.error;if(history.error)throw history.error;
  if(token!==statusLoadToken||!target.isConnected)return;
  const rows=components.data||[],changes=history.data||[];
  if(!rows.length){target.innerHTML=empty('No components configured',ownerMode?'Run the status setup SQL to create the fixed service list.':'OTV has not published its service components yet.');return;}
  const overall=statusOverall(rows),issues=rows.filter(r=>['outage','degraded'].includes(r.status)),maintenance=rows.filter(r=>r.status==='maintenance');
  const headings={outage:'Some OTV services are unavailable',degraded:'Some services aren’t running normally',maintenance:'Maintenance is in progress',operational:'All services are operational',unknown:'Some services haven’t been checked yet'};
  const recent=rows.map(r=>r.updated_at).filter(Boolean).sort().at(-1);
  target.innerHTML=`<div class="service-page ${ownerMode?'service-owner':''}">${ownerMode?'<div class="service-owner-intro"><p>Choose a component to update it. Your explanation is public.</p><a href="#status">View public status →</a></div>':'<div class="service-heading"><span class="eyebrow">OTV service status</span><h1>Keeping you in the picture.</h1><p class="muted">Updates from the OTV team, for viewers and creators.</p></div>'}<div class="service-summary summary-${overall}" role="status"><span class="service-summary-dot" aria-hidden="true"></span><div><h2>${headings[overall]}</h2><p>${recent?'Last team update: '+statusTime(recent)+' UK time.':'Awaiting the first team update.'} Manually maintained by OTV.</p></div><button type="button" data-status-refresh>Refresh</button></div><div class="service-columns"><section><h2>Our services</h2>${statusGroups.map(([id,name])=>{const members=rows.filter(r=>r.group_id===id);if(!members.length)return '';return `<details class="service-group" ${ownerMode||statusOverall(members)!=='operational'?'open':''}><summary><span>${name}</span>${statusBadge(statusOverall(members))}</summary><div class="service-components">${members.map(r=>`<div class="service-component"><div class="service-component-top"><span class="service-component-name">${esc(r.name)}</span>${statusBadge(r.status)}${ownerMode?`<button type="button" class="service-edit" data-status-edit="${esc(r.id)}" aria-label="Update ${esc(r.name)}">Update</button>`:''}</div>${r.reason?`<p class="service-reason">${esc(r.reason)}</p>`:''}${statusMaintenance(r)}</div>`).join('')}</div></details>`}).join('')}<p class="service-footnote">Off air is normal between broadcasts. It does not mean the live player is broken.</p></section><aside><h2>Current incidents</h2>${issues.length?issues.map(r=>`<article class="service-incident state-${r.status}"><span class="eyebrow">${statusNames[r.status]}</span><h3>${esc(r.name)}</h3><p class="service-reason">${esc(r.reason)}</p><small>Updated ${statusTime(r.updated_at)} UK time</small></article>`).join(''):'<p class="muted">No active incidents reported.</p>'}<section class="service-maintenance"><h2>Maintenance</h2>${maintenance.length?maintenance.map(r=>`<article class="service-incident state-maintenance"><h3>${esc(r.name)}</h3><p class="service-reason">${esc(r.reason)}</p>${statusMaintenance(r)}</article>`).join(''):'<p class="muted">No maintenance in progress.</p>'}</section></aside></div>${statusHistory(changes,rows)}<p class="service-footnote">Times shown in Europe/London. Statuses describe OTV services, not the availability of every individual video.</p></div>`;
  target.querySelector('[data-status-refresh]').onclick=()=>renderStatusPage(target,ownerMode);
  target.querySelectorAll('[data-status-edit]').forEach(button=>button.onclick=()=>openStatusEditor(rows.find(r=>r.id===button.dataset.statusEdit),()=>renderStatusPage(target,true)));
 }catch(error){if(token!==statusLoadToken||!target.isConnected)return;target.innerHTML=`<section class="service-error"><h2>We couldn’t load service status.</h2><p class="muted">Please try again. Service availability is unconfirmed while this page can’t connect.</p>${ownerMode?`<p>${esc(error.message||'Check the Supabase connection and run 004_status.sql.')}</p>`:''}<button type="button" data-status-retry>Try again</button></section>`;target.querySelector('[data-status-retry]').onclick=()=>renderStatusPage(target,ownerMode);}
}
function openStatusEditor(component,afterSave){
 if(role!=='admin'||!component)return;
 const dialog=$('#dialog'),body=$('#dialog-body');
 let busy=false,retry=null;
 body.innerHTML=`<h2 id="status-editor-title">${esc(component.name)}</h2><p class="muted">Update this component. No new component will be created.</p><form id="service-status-form"><fieldset class="service-status-options"><legend>Service status</legend>${['operational','degraded','outage','maintenance'].map(s=>`<label><input type="radio" name="service_status" value="${s}" ${component.status===s?'checked':''} required><span>${statusNames[s]}</span></label>`).join('')}</fieldset><label><span id="status-reason-label">Public explanation</span><textarea name="reason" maxlength="1200" rows="4">${esc(component.reason)}</textarea></label><div id="status-duration-fields" hidden><label>Expected downtime, in minutes<input type="number" name="maintenance_minutes" min="1" max="43200" step="1" value="${component.maintenance_minutes||60}" disabled></label><p class="muted">${component.status==='maintenance'?`Total planned duration from ${statusTime(component.maintenance_started_at)} UK time. Changing the explanation won’t restart the clock.`:'The estimate starts when you save.'} Mark Operational yourself when maintenance is finished.</p></div><p id="service-save-message" role="status" aria-live="polite"></p><div class="actions"><button type="submit" class="primary">Save status</button><button type="button" id="service-cancel">Cancel</button></div></form>`;
 dialog.setAttribute('aria-labelledby','status-editor-title');
 const form=body.querySelector('form'),duration=body.querySelector('#status-duration-fields'),message=body.querySelector('#service-save-message');
 const updateFields=()=>{const selected=form.elements.service_status.value;duration.hidden=selected!=='maintenance';form.elements.maintenance_minutes.disabled=selected!=='maintenance';form.elements.maintenance_minutes.required=selected==='maintenance';form.elements.reason.required=selected!==''&&selected!=='operational';body.querySelector('#status-reason-label').textContent=selected==='operational'?'Resolution note (optional)':'Why is this component affected?';};
 form.elements.service_status.forEach(input=>input.addEventListener('change',()=>{retry=null;if(input.value!==component.status)form.elements.reason.value='';updateFields();}));
 body.querySelector('#service-cancel').onclick=()=>dialog.close();updateFields();dialog.showModal();
 const preventClose=e=>{if(busy)e.preventDefault()};dialog.addEventListener('cancel',preventClose);dialog.addEventListener('close',()=>{dialog.removeEventListener('cancel',preventClose);dialog.removeAttribute('aria-labelledby')},{once:true});
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;
  try{
   const v=validateStatusDraft(form.elements.service_status.value,form.elements.reason.value,form.elements.maintenance_minutes.value);
   const fingerprint=JSON.stringify(v);
   if(!retry||retry.fingerprint!==fingerprint)retry={fingerprint,id:crypto.randomUUID()};
   busy=true;message.textContent='Saving…';form.querySelectorAll('button').forEach(b=>b.disabled=true);$('#close-dialog').disabled=true;
   const {error}=await db.rpc('set_component_status',{p_component_id:component.id,p_status:v.status,p_reason:v.reason,p_maintenance_minutes:v.minutes,p_expected_revision:component.revision,p_request_id:retry.id});
   if(error)throw error;
   busy=false;dialog.close();notify('Status saved. The existing component has been updated.');await afterSave();
  }catch(error){message.textContent=error.message||'Could not save. Please try again.';}
  finally{busy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);$('#close-dialog').disabled=false;}
 };
}

function programmePage(show,episodes){
 const articles=published(data.articles).filter(x=>x.programme_id===show.id);
 const related=published(data.programmes).filter(x=>x.id!==show.id&&show.category&&x.category===show.category).slice(0,4);
 const logo=safe(show.show_logo),backdrop=safe(show.banner);
 const episodeCards=episodes.map(ep=>`<a class="programme-episode" href="#episode/${ep.id}"><div class="programme-episode-art">${art(ep.thumbnail)}${ep.duration?`<span class="programme-duration">${esc(ep.duration)}</span>`:''}<span class="programme-play" aria-hidden="true">▶</span></div><div class="programme-episode-meta">${[ep.season?'Series '+esc(ep.season):'',ep.episode_number?'Episode '+esc(ep.episode_number):'',ep.publish_at?stamp(ep.publish_at):''].filter(Boolean).join(' · ')}</div><h3>${esc(ep.title)}</h3>${ep.description?`<p>${esc(ep.description)}</p>`:''}</a>`).join('');
 return `<section class="programme-hero"><div class="programme-backdrop">${backdrop?`<img src="${esc(backdrop)}" alt="" fetchpriority="high">`:''}</div><div class="programme-fade" aria-hidden="true"></div><div class="programme-hero-content"><a class="programme-back" href="#shows">← All shows</a>${show.category?`<span class="eyebrow">${esc(show.category)}</span>`:''}<h1>${logo?`<img class="programme-logo" src="${esc(logo)}" alt="${esc(show.title)}">`:esc(show.title)}</h1>${show.description?`<p class="programme-description">${esc(show.description)}</p>`:''}<div class="programme-actions">${episodes.length?`<a class="button primary" href="#episode/${episodes[0].id}">▶ &nbsp; Watch latest episode</a>`:'<span class="programme-coming">Episodes coming soon</span>'}<button id="favourite" data-id="${show.id}">＋ Favourite show</button></div></div></section><div class="programme-body"><section class="programme-episodes"><div class="section-head"><h2>Episodes</h2><span class="muted">${episodes.length} ${episodes.length===1?'episode':'episodes'}</span></div>${episodes.length?`<div class="programme-episode-grid">${episodeCards}</div>`:'<p class="programme-empty">The first episode will appear here when it’s published.</p>'}</section><section class="programme-about"><div><span class="eyebrow">Behind the programme</span><h2>About ${esc(show.title)}</h2><p class="reader-body">${esc(show.body||show.description||'More about this programme soon.')}</p></div><dl>${show.creator?`<div><dt>Created by</dt><dd>${esc(show.creator)}</dd></div>`:''}${show.category?`<div><dt>Category</dt><dd>${esc(show.category)}</dd></div>`:''}${show.premiere_date?`<div><dt>First aired</dt><dd>${stamp(show.premiere_date)}</dd></div>`:''}</dl></section>${articles.length?`<section class="programme-news">${head('From the programme')}${cards(articles,'article')}</section>`:''}${related.length?`<section class="programme-related">${head('You might also like')}${cards(related,'show')}</section>`:''}</div>`;
}

const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:''}catch{return ''}};
export function youtube(value){const s=String(value||'');const src=s.match(/src=["']([^"']+)/)?.[1]||s;try{const u=new URL(src);if(['youtu.be','www.youtu.be'].includes(u.hostname))return /^[\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):'';if(!['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname))return '';const id=u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|live|shorts)\/([\w-]+)/)?.[1];return /^[\w-]{11}$/.test(id||'')?id:''}catch{return ''}}
let db=null,user=null,role='viewer',permissions={},data={},settings={},tab='Overview',authMode='Sign in';const tables=['programmes','episodes','articles','broadcasts','announcements','show_hub_published'];
const cfg=window.OTV_CONFIG||{};const configured=!!(cfg.supabaseUrl&&cfg.supabaseKey);let loadError='';
if(sessionStorage.getItem('otv-intro'))$('#intro').remove();else sessionStorage.setItem('otv-intro','1');
const notify=t=>{$('#notice').textContent=t};
async function query(t){const {data,error}=await db.from(t).select('*');if(error)throw error;return data||[]}
async function refresh(){if(!db){tables.forEach(t=>data[t]=[]);return}try{await Promise.all(tables.map(async t=>data[t]=await query(t)));const rows=await query('settings');settings=rows.find(r=>r.id==='site')?.value||{};loadError=''}catch(e){loadError=e.message;notify('Content could not be loaded. '+e.message)}}
const published=a=>(a||[]).filter(x=>x.status==='published'&&(!x.publish_at||new Date(x.publish_at)<=new Date()));
const art=(url,cls='')=>`<div class="art ${cls}">${safe(url)?`<img src="${esc(safe(url))}" alt="" loading="lazy">`:''}</div>`;
const empty=(title,desc)=>`<div class="empty"><h2>${esc(title)}</h2><p>${esc(desc)}</p></div>`;
const cards=(rows,type)=>richerCards(rows,type);
const placeholders=()=>`<div class="grid empty-cards" aria-hidden="true">${Array.from({length:6},()=>'<div><div class="art"></div><i></i><i></i></div>').join('')}</div>`;
const head=(title,href,label='View all')=>`<div class="section-head"><h2>${title}</h2>${href?`<a href="#${href}">${label} &nbsp; →</a>`:''}</div>`;
const stamp=v=>v?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'';
const time=v=>new Date(v).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:settings.timezone||'Europe/London'});
function schedule(rows){return rows.length?rows.sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).map(x=>`<div class="schedule-item"><time>${time(x.starts_at)}</time>${art(x.thumbnail)}<div><b>${esc(x.title)}</b><p class="muted">${esc(x.description||'')}</p></div>${x.broadcast_status==='live'?'<span class="badge red">Marked live by OTV</span>':''}</div>`).join(''):'<div class="empty-schedule"><strong>—</strong><span>No broadcasts scheduled.<br>Check back for the next line-up.</span></div>'}
function themeActive(){return (!settings.theme_starts||new Date(settings.theme_starts)<=new Date())&&(!settings.theme_ends||new Date(settings.theme_ends)>new Date())}
function featuredBanner(feature,fallback){const backdrop=safe(feature?.banner||fallback);const title=feature?.title||(themeActive()&&settings.theme_headline)||settings.headline||'Original Shows.\nLive Events.\nMade in Roblox.';const description=feature?.description||settings.description||'Entertainment, news, gameshows and more — all on OTV.';return `<div class="art hero-art show-feature">${backdrop?`<img class="show-backdrop" src="${esc(backdrop)}" alt="" fetchpriority="high">`:''}<div class="show-feature-shade" aria-hidden="true"></div><div class="hero-caption show-feature-copy"><span class="eyebrow">${feature?'Featured on OTV':'Open Television'}</span><h1 class="show-feature-title">${safe(feature?.show_logo)?`<img class="show-feature-logo" src="${esc(safe(feature.show_logo))}" alt="${esc(title)}">`:esc(title).replace(/\n/g,'<br>')}</h1>${description?`<p class="show-feature-description">${esc(description)}</p>`:''}<div class="show-feature-actions">${feature?`<a class="button primary" href="#show/${feature.id}">Explore show <span aria-hidden="true">→</span></a>`:'<a class="button primary" href="#live">▶ &nbsp; Watch Live</a>'}<a class="show-browse" href="#shows">Browse shows <span aria-hidden="true">→</span></a></div></div></div>`}
function home(){const shows=published(data.programmes),episodes=published(data.episodes).sort((a,b)=>new Date(b.publish_at)-new Date(a.publish_at)),news=published(data.articles);const live=published(data.broadcasts).find(x=>x.broadcast_status==='live');const upcoming=published(data.broadcasts).filter(x=>new Date(x.starts_at)>new Date());const today=published(data.broadcasts).filter(x=>new Date(x.starts_at).toLocaleDateString('en-GB',{timeZone:settings.timezone||'Europe/London'})===new Date().toLocaleDateString('en-GB',{timeZone:settings.timezone||'Europe/London'}));const feature=shows.find(x=>x.featured);const sections={hero:`<section class="hero hero-wide">${featuredBanner(feature,settings.banner)}</section>`,shows:`<section class="section">${head('Popular Shows','shows')}${shows.length?cards(shows.filter(x=>x.featured).length?shows.filter(x=>x.featured).slice(0,6):shows.slice(0,6),'show'):placeholders() }${!shows.length?'<p class="empty-note">The next chapter starts here. Programmes will appear as they’re published.</p>':''}</section>`,live:`<section class="broadcast-row"><div class="panel"><h2><span class="dot"></span>Live Now</h2><div class="art live-art"><span class="badge ${live?'red':''}">${live?'Marked live by OTV':'Off air'}</span><div class="live-bottom"><div><h3>${esc(live?.title||'We’ll be back on air soon.')}</h3><p>${esc(live?.description||'Your next live moment starts here.')}</p></div><a class="button primary" href="#live">${live?'▶ Watch':'Live hub →'}</a></div></div></div><div class="panel">${head('Up Next')}${schedule(upcoming.slice(0,3))}</div><div class="panel">${head('Today’s Schedule','schedule','Full schedule')}${schedule(today.slice(0,4))}</div></section>`,episodes:`<section class="section">${head('Latest Episodes','episodes')}${episodes.length?cards(episodes.slice(0,6),'episode'):placeholders()}${!episodes.length?'<p class="empty-note">Catch-up episodes will be available here after publication.</p>':''}</section>`,news:`<section class="section">${head('From the OTV Newsroom','news')}${news.length?cards(news.slice(0,6),'article'):'<p class="empty-note">News and announcements from the network, as they happen.</p>'}</section>`};const order=[...new Set(settings.sections||['hero','episodes','shows','live','news'])];if(order.includes('episodes')){order.splice(order.indexOf('episodes'),1);order.splice(order.includes('hero')?order.indexOf('hero')+1:0,0,'episodes')}if(order.includes('episodes')&&!(settings.hidden||[]).includes('episodes')){sections.continue=continueWatching();order.splice(order.indexOf('episodes')+1,0,'continue')}return order.filter(k=>!(settings.hidden||[]).includes(k)).map(k=>sections[k]||'').join('')}
function listing(kind,title){const rows=published(data[kind]);return `<div class="page-top"><span class="eyebrow">Explore OTV</span><h1>${title}</h1><p class="muted">${kind==='programmes'?'Find your next favourite programme.':kind==='articles'?'The latest from our network and our community.':'Watch the latest, in your own time.'}</p></div><div class="filters"><input id="filter-text" placeholder="Search ${title.toLowerCase()}" aria-label="Filter by title"><select id="filter-category" aria-label="Category"><option value="">All categories</option>${[...new Set(rows.map(x=>x.category).filter(Boolean))].map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="listing-results"></div>`}
function listResults(kind){const rows=published(data[kind]).filter(x=>`${x.title} ${x.description} ${x.tags||''}`.toLowerCase().includes(($('#filter-text')?.value||'').toLowerCase())&&(!$('#filter-category')?.value||x.category===$('#filter-category').value));$('#listing-results').innerHTML=rows.length?cards(rows,kind==='programmes'?'show':kind==='episodes'?'episode':'article'):empty('Nothing here just yet','Published content will appear here. Try another search or check back soon.')}
function player(x,track=false){return enhancedPlayer(x,track)}
function detail(type,id){const table={show:'programmes',episode:'episodes',article:'articles'}[type],x=published(data[table]).find(x=>x.id===id);if(!x)return empty('Page not found','This content may be unpublished or no longer available.');if(type==='episode')return `<a href="#show/${x.programme_id}">← Programme</a><div class="page-top"><h1>${esc(x.title)}</h1><p class="muted">${stamp(x.publish_at)}</p></div>${player(x,true)}<p>${esc(x.description)}</p>`;if(type==='article')return `<article class="reader"><span class="eyebrow">${esc(x.category||'OTV News')}</span><h1>${esc(x.title)}</h1><p>${esc(x.description)}</p><p class="muted">${esc(x.author||'OTV')} · ${stamp(x.publish_at)}</p>${art(x.thumbnail)}<div class="reader-body">${esc(x.body)}</div>${x.youtube_url?player(x):''}</article>`;const eps=published(data.episodes).filter(e=>e.programme_id===id).sort((a,b)=>new Date(b.publish_at)-new Date(a.publish_at));return showHubPage(x,eps)}
function account(){if(user)return `<div class="account"><span class="eyebrow">Your OTV</span><h1>Your account</h1><p>${esc(user.email)}</p><form id="profile-form" class="stack"><label>Display name<input name="display_name" value="${esc(user.user_metadata?.display_name||'')}"></label><button>Save display name</button></form><div class="actions">${['admin','developer'].includes(role)?'<a class="button primary" href="#control">Open control room →</a>':''}<button id="signout">Sign out</button></div><h2 class="section">Favourite shows</h2><div id="favourites"></div></div>`;return `<div class="account"><span class="eyebrow">Welcome to OTV</span><h1>${authMode}</h1><p class="muted">Watching is always open. An account is just for your favourites and contributions.</p>${!configured?'<div class="panel muted">Accounts are not connected yet. The site owner needs to complete the Supabase setup.</div>':''}<div class="tabs">${['Sign in','Sign up','Reset password'].map(t=>`<button data-auth="${t}" class="${t===authMode?'selected':''}">${t}</button>`).join('')}</div><form id="auth-form" class="stack"><label>Email<input name="email" type="email" autocomplete="email" required></label>${authMode!=='Reset password'?'<label>Password<input name="password" type="password" minlength="8" autocomplete="current-password" required></label>':''}<button class="primary" ${!db?'disabled':''}>${authMode}</button></form></div>`}
const fields={programmes:{title:'text',description:'textarea',body:'textarea',category:'text',tags:'text',creator:'text',premiere_date:'date',thumbnail:'url',banner:'url',show_logo:'url',accent_color:'color',featured:'checkbox'},episodes:{title:'text',programme_id:'programme',description:'textarea',season:'number',episode_number:'number',youtube_url:'text',duration:'text',thumbnail:'url'},articles:{title:'text',description:'textarea',author:'text',category:'text',programme_id:'programme',body:'textarea',youtube_url:'text',thumbnail:'url'},broadcasts:{title:'text',programme_id:'programme',description:'textarea',starts_at:'datetime-local',ends_at:'datetime-local',youtube_url:'text',broadcast_status:['scheduled','live','ended','cancelled'],thumbnail:'url'},announcements:{title:'text',description:'textarea',expires_at:'datetime-local',link:'url'}};
const tabTable={'Shows':'programmes','Episodes':'episodes','Newsroom':'articles','Schedule':'broadcasts','Live Control':'broadcasts','Announcements':'announcements'};
function control(){if(!user||!['admin','developer'].includes(role))return empty('Control room access required','Sign in with an approved OTV team account.');const tabs=role==='admin'?['Overview',...Object.keys(tabTable),'Website Management','Website Themes','Status','Developer Applications','Users & Permissions','Media Library','Activity Logs']:['Overview',...Object.keys(tabTable).filter(t=>permissions[tabTable[t]]),'Media Library'];return `<div class="page-top"><span class="eyebrow">OTV / ${role==='admin'?'Owner control room':'Developer portal'}</span><h1>${tab}</h1><p class="muted">${role==='admin'?'Your network. Every detail.':'Create, prepare and submit your work.'}</p></div><div class="admin-layout"><aside class="sidebar">${tabs.map(t=>`<button data-tab="${t}" class="${tab===t?'selected':''}">${t}</button>`).join('')}</aside><div id="admin-content"></div></div>`}
async function adminContent(){const el=$('#admin-content');if(!el)return;if(tab==='Status'){await renderStatusPage(el,true);return}const t=tabTable[tab];if(t){const rows=data[t]||[];el.innerHTML=`<div class="section-head"><p class="muted">${rows.length} items · Drafts stay private until published.</p><button id="new-item" class="primary">＋ Create ${tab==='Newsroom'?'article':tab==='Shows'?'show':'item'}</button></div><table class="admin-table"><thead><tr><th>Title</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.title)}</td><td><span class="badge">${esc(x.status)}</span></td><td><button data-edit="${x.id}">Edit</button> ${t==='programmes'?`<button data-hub="${x.id}">Page builder</button>`:''} <button data-delete="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table>${!rows.length?empty('Ready for your first item','Create a draft, then publish when it’s ready.'):''}`;$('#new-item').onclick=()=>editor(t);el.querySelectorAll('[data-hub]').forEach(b=>b.onclick=()=>openShowHubBuilder(rows.find(x=>x.id===b.dataset.hub)));el.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(t,rows.find(x=>x.id===b.dataset.edit)));el.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Permanently delete this item?'))await action(async()=>{const {error}=await db.from(t).delete().eq('id',b.dataset.delete);if(error)throw error;await refresh();adminContent()})});return}
if(tab==='Overview'){el.innerHTML=`<div class="stats">${['programmes','episodes','articles','broadcasts'].map(t=>`<div class="panel stat"><span class="muted">${t}</span><strong>${(data[t]||[]).length}</strong></div>`).join('')}</div><div class="panel section"><h2>On the desk</h2><p class="muted">${tables.filter(t=>t!=='show_hub_published').reduce((n,t)=>n+(data[t]||[]).filter(x=>x.status==='draft'||x.status==='review').length,0)} items in draft or review.</p><p>Use the sections on the left to manage your content.</p></div>`;return}
if(tab==='Website Management'||tab==='Website Themes'){const theme=tab==='Website Themes';el.innerHTML=`<form id="settings-form"><div class="editor-grid">${(theme?['theme','accent','theme_headline','theme_starts','theme_ends']:['headline','description','banner','footer','timezone','sections','hidden','contact_email']).map(k=>`<label>${k.replaceAll('_',' ')}${k==='theme'?`<select name="theme">${['default','christmas','halloween','uk-election','us-midterms','special'].map(v=>`<option ${settings.theme===v?'selected':''}>${v}</option>`).join('')}</select>`:`<input name="${k}" value="${esc(Array.isArray(settings[k])?settings[k].join(','):settings[k]||'')}" ${k.includes('starts')||k.includes('ends')?'type="datetime-local"':''}>`}</label>`).join('')}</div><p class="muted">${theme?'Theme dates use your local time. Leave dates empty for immediate activation.':'Section order: hero,shows,live,episodes,news. Hidden sections: comma-separated keys.'}</p><div class="actions"><button type="button" id="preview-settings">Preview</button><button class="primary">Save changes</button></div></form><div id="settings-preview" class="section"></div>`;const values=()=>{const v=Object.fromEntries(new FormData($('#settings-form')));for(const k of ['sections','hidden'])if(k in v)v[k]=v[k].split(',').map(x=>x.trim()).filter(Boolean);for(const k of ['theme_starts','theme_ends'])if(v[k])v[k]=new Date(v[k]).toISOString();if(v.timezone){try{new Intl.DateTimeFormat('en-GB',{timeZone:v.timezone})}catch{throw Error('Enter a valid timezone, such as Europe/London.')}}return {...settings,...v}};$('#preview-settings').onclick=()=>{const old=settings;try{settings=values();$('#settings-preview').innerHTML=home()}catch(e){notify(e.message)}finally{settings=old}};$('#settings-form').onsubmit=e=>{e.preventDefault();action(async()=>{const {error}=await db.from('settings').upsert({id:'site',value:values()});if(error)throw error;await refresh();notify('Website settings saved.');render()})};return}
if(tab==='Developer Applications'){const rows=await query('applications');el.innerHTML=rows.map(x=>`<div class="panel section"><h3>${esc(x.display_name)}</h3><p>${esc(x.reason)}</p><p class="muted">${esc(x.roblox_username)} · ${esc(x.status)}</p>${x.status==='pending'?`<button data-approve="${x.id}">Approve</button> <button data-reject="${x.id}">Reject</button>`:''}</div>`).join('')||empty('No applications','New contributor applications appear here.');for(const b of el.querySelectorAll('[data-approve],[data-reject]'))b.onclick=()=>action(async()=>{const {error}=await db.rpc('review_application',{application_id:b.dataset.approve||b.dataset.reject,approve:!!b.dataset.approve});if(error)throw error;await adminContent()});return}
if(tab==='Users & Permissions'){const rows=await query('roles');el.innerHTML=`<p class="muted">Developer capabilities and publication permission are enforced in the database.</p>${rows.map(x=>`<div class="panel section"><b>${esc(x.user_id)}</b> · ${esc(x.role)}${x.role==='developer'?`<form data-permissions="${x.user_id}">${['programmes','episodes','articles','broadcasts','announcements','publish'].map(k=>`<label><span><input type="checkbox" name="${k}" ${x.permissions[k]?'checked':''}> ${k}</span></label>`).join('')}<button>Save permissions</button></form>`:''}</div>`).join('')}`;el.querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(async()=>{const p=Object.fromEntries([...new FormData(f)].map(([k])=>[k,true]));const {error}=await db.from('roles').update({permissions:p}).eq('user_id',f.dataset.permissions);if(error)throw error;notify('Permissions saved.')})});return}
if(tab==='Media Library'){el.innerHTML='<h2>Upload artwork</h2><p class="muted">JPEG, PNG or WebP, up to 5 MB. Copy the resulting URL into a content image field.</p><input type="file" id="upload" accept="image/jpeg,image/png,image/webp"><div id="media-results" class="grid section"></div>';const rows=await query('media');$('#media-results').innerHTML=rows.map(x=>`<div>${art(x.url)}<label>Image URL<input readonly value="${esc(x.url)}"></label></div>`).join('');$('#upload').onchange=e=>action(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Choose a JPEG, PNG or WebP under 5 MB.');const path=`${user.id}/${crypto.randomUUID()}.${f.type.split('/')[1]}`;const {error}=await db.storage.from('otv-media').upload(path,f);if(error)throw error;const url=db.storage.from('otv-media').getPublicUrl(path).data.publicUrl;const r=await db.from('media').insert({owner_id:user.id,path,url});if(r.error)throw r.error;adminContent()});return}
if(tab==='Activity Logs'){const rows=await query('activity');el.innerHTML=rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(x=>`<div class="schedule-item"><time>${stamp(x.created_at)}</time><span>${esc(x.action)} · ${esc(x.entity)}<br><small>${esc(x.actor_id)}</small></span></div>`).join('')||empty('No activity yet','Content changes will be recorded here.')}}
function editor(t,row={}){const canPublish=role==='admin'||permissions.publish;$('#dialog-body').innerHTML=`<h2>${row.id?'Edit':'Create'} ${t}</h2><form id="editor"><div class="editor-grid">${Object.entries(fields[t]).map(([k,type])=>{let v=row[k]??(k==='accent_color'?'#d2c1ed':'');if(type==='datetime-local'&&v)v=new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16);const opts=type==='programme'?data.programmes:[];return `<label>${k==='accent_color'?'Show accent colour':k==='show_logo'?'Show logo URL (transparent PNG recommended)':k==='banner'?'Backdrop image URL':k.replaceAll('_',' ')}${Array.isArray(type)?`<select name="${k}">${type.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select>`:type==='programme'?`<select name="${k}" ${t==='episodes'?'required':''}><option value="">Select programme</option>${opts.map(o=>`<option value="${o.id}" ${o.id===v?'selected':''}>${esc(o.title)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${k}">${esc(v)}</textarea>`:`<input name="${k}" type="${type}" ${type==='checkbox'?(v?'checked':''):`value="${esc(v)}"`} ${k==='title'?'required':''}>`}</label>`}).join('')}<label>Publication status<select name="status">${['draft','review',...(canPublish?['published']:[])].map(s=>`<option ${row.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Publication date / time<input type="datetime-local" name="publish_at" value="${row.publish_at?new Date(new Date(row.publish_at).getTime()-new Date(row.publish_at).getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></label></div><p class="muted">A published item with a future date stays private until that time. Article text is rendered safely as paragraphs.</p><button class="primary">Save ${row.id?'changes':'item'}</button></form>`;if(t==='programmes')setupShowEditorPreview($('#editor'),row);$('#dialog').showModal();$('#editor').onsubmit=e=>{e.preventDefault();action(async()=>{const values=Object.fromEntries(new FormData(e.target));for(const [k,type]of Object.entries(fields[t])){if(type==='checkbox')values[k]=!!e.target.elements[k].checked;else if(type==='number')values[k]=values[k]?Number(values[k]):null;else if(type==='datetime-local'||type==='date'||type==='programme')values[k]=values[k]?(type==='datetime-local'?new Date(values[k]).toISOString():values[k]):null}values.publish_at=values.publish_at?new Date(values.publish_at).toISOString():new Date().toISOString();if(values.youtube_url&&!youtube(values.youtube_url))throw Error('Enter a valid YouTube video link or iframe embed.');if(values.youtube_url)values.youtube_url=`https://www.youtube.com/watch?v=${youtube(values.youtube_url)}`;if(values.starts_at&&values.ends_at&&values.ends_at<=values.starts_at)throw Error('End time must be after start time.');let q=row.id?db.from(t).update(values).eq('id',row.id):db.from(t).insert({...values,owner_id:user.id});const {error}=await q;if(error)throw error;$('#dialog').close();await refresh();adminContent();notify('Saved to OTV.')})}}
async function action(fn){try{if(!db)throw Error('Connect Supabase to enable this feature.');await fn()}catch(e){notify(e.message||'Something went wrong. Please try again.')}}
async function render(){stopWatch();statusLoadToken++;const [route='home',id]=location.hash.slice(1).split('/');$('#nav').innerHTML=['Home','Shows','Live','News','Schedule','About','Status'].filter(x=>!(settings.hidden||[]).includes(x.toLowerCase())).map(x=>`<a href="#${x.toLowerCase()}" class="${route===x.toLowerCase()?'active':''}">${x}</a>`).join('');document.body.dataset.theme=settings.theme||'default';const active=(!settings.theme_starts||new Date(settings.theme_starts)<=new Date())&&(!settings.theme_ends||new Date(settings.theme_ends)>new Date());document.documentElement.style.setProperty('--accent',active&&/^#[\da-f]{6}$/i.test(settings.accent||'')?settings.accent:active?({christmas:'#b5d2b7',halloween:'#e2a46e','uk-election':'#c2c9f0','us-midterms':'#c2c9f0'}[settings.theme]||'#d2c1ed'):'#d2c1ed');const m=$('#main');m.classList.toggle('home-page',route==='home');m.classList.toggle('programme-page',route==='show'&&published(data.programmes).some(x=>x.id===id));const announcement=published(data.announcements).find(x=>!x.expires_at||new Date(x.expires_at)>new Date());if(announcement)notify(announcement.title+' — '+announcement.description);if(settings.footer)document.querySelector('footer p').textContent=settings.footer;if(route==='home')m.innerHTML=home();else if(['shows','episodes','news'].includes(route)){const t={shows:'programmes',episodes:'episodes',news:'articles'}[route];m.innerHTML=listing(t,{shows:'Our Shows',episodes:'Latest Episodes',news:'OTV News'}[route]);listResults(t);$('#filter-text').oninput=()=>listResults(t);$('#filter-category').onchange=()=>listResults(t)}else if(['show','episode','article'].includes(route))m.innerHTML=detail(route,id);else if(route==='live'&&(settings.hidden||[]).includes('live'))m.innerHTML=empty('Live broadcasting is currently unavailable','Browse our shows or check the schedule for future programmes.');else if(route==='live'){m.innerHTML=livePage()}else if(route==='schedule'){m.innerHTML=`<div class="page-top"><span class="eyebrow">The OTV line-up</span><h1>What’s on.</h1><p class="muted">Times shown in ${esc(settings.timezone||'Europe/London')}.</p></div><label>Choose a date<input type="date" id="schedule-date" value="${new Date().toLocaleDateString('en-CA',{timeZone:settings.timezone||'Europe/London'})}"></label><div class="panel" id="day-schedule"></div>`;const update=()=>$('#day-schedule').innerHTML=schedule(published(data.broadcasts).filter(x=>new Date(x.starts_at).toLocaleDateString('en-CA',{timeZone:settings.timezone||'Europe/London'})===$('#schedule-date').value));$('#schedule-date').onchange=update;update()}else if(route==='about')m.innerHTML='<article class="reader"><span class="eyebrow">Open Television</span><h1>Made in Roblox.<br>Made for everyone.</h1><p>OTV is an independent entertainment and television network built around the Roblox community.</p><p class="muted">A home for original programmes, live events, news and the people who make them.</p><a class="button" href="#apply">Create with OTV →</a></article>'+(settings.contact_email&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(settings.contact_email)?'<p class="reader">Contact: '+esc(settings.contact_email)+'</p>':'');else if(route==='status'){await renderStatusPage(m)}else if(route==='account')m.innerHTML=account();else if(route==='control'){m.innerHTML=control();await action(adminContent)}else if(route==='apply'){m.innerHTML=`<div class="account"><span class="eyebrow">Create with OTV</span><h1>Join the team.</h1><p class="muted">Tell us what you’d like to create. Every application is reviewed by the OTV owner.</p>${!user?'<a class="button primary" href="#account">Sign in or create an account</a>':'<form id="apply-form"><label>Display name<input name="display_name" required></label><label>Roblox username (optional)<input name="roblox_username"></label><label>Why would you like to join?<textarea name="reason" required></textarea></label><button class="primary">Submit application</button></form>'}</div>`}else if(route==='search'){const q=decodeURIComponent(id||'');m.innerHTML=`<div class="page-top"><h1>Search OTV</h1><p class="muted">Results for “${esc(q)}”</p></div>`+['programmes','episodes','articles'].map(t=>`<section class="section">${head(t==='programmes'?'Shows':t==='articles'?'News':'Episodes')}${cards(published(data[t]).filter(x=>`${x.title} ${x.description}`.toLowerCase().includes(q.toLowerCase())),t==='programmes'?'show':t==='articles'?'article':'episode')}</section>`).join('')}else if(route==='reset')m.innerHTML='<div class="account"><h1>Choose a new password</h1><form id="password-form"><label>New password<input type="password" name="password" minlength="8" required></label><button>Update password</button></form></div>';else m.innerHTML=empty('404 — Off the schedule','This page doesn’t exist. Choose a section in the navigation.');bind();enhancePage();animatePage(m);}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>{authMode=b.dataset.auth;render()});if($('#auth-form'))$('#auth-form').onsubmit=e=>{e.preventDefault();action(async()=>{const v=Object.fromEntries(new FormData(e.target));let r;if(authMode==='Sign up')r=await db.auth.signUp({...v,options:{emailRedirectTo:location.href.split('#')[0]+'#account'}});else if(authMode==='Reset password')r=await db.auth.resetPasswordForEmail(v.email,{redirectTo:location.href.split('#')[0]+'#reset'});else r=await db.auth.signInWithPassword(v);if(r.error)throw r.error;notify(authMode==='Sign up'?'Check your email to verify your account.':authMode==='Reset password'?'If an account exists, a reset email has been requested.':'Signed in.');await session();render()})};if($('#signout'))$('#signout').onclick=()=>action(async()=>{await db.auth.signOut();await session();render()});if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();action(async()=>{const {error}=await db.auth.updateUser({data:Object.fromEntries(new FormData(e.target))});if(error)throw error;notify('Display name updated.')})};if($('#password-form'))$('#password-form').onsubmit=e=>{e.preventDefault();action(async()=>{const {error}=await db.auth.updateUser({password:new FormData(e.target).get('password')});if(error)throw error;notify('Password updated.');location.hash='account'})};if($('#apply-form'))$('#apply-form').onsubmit=e=>{e.preventDefault();action(async()=>{const {error}=await db.from('applications').insert({...Object.fromEntries(new FormData(e.target)),user_id:user.id});if(error)throw error;notify('Application submitted for owner approval.');e.target.reset()})};if($('#favourite'))$('#favourite').onclick=()=>action(async()=>{if(!user){location.hash='account';return}const {error}=await db.from('favourites').upsert({user_id:user.id,programme_id:$('#favourite').dataset.id});if(error)throw error;notify('Added to your favourites.')});if($('#favourites'))action(async()=>{const rows=await query('favourites');$('#favourites').innerHTML=cards(published(data.programmes).filter(x=>rows.some(r=>r.programme_id===x.id)),'show')||'<p>No favourites yet.</p>'})}
async function session(){user=(await db.auth.getSession()).data.session?.user||null;role='viewer';permissions={};if(user){const r=await db.from('roles').select('*').eq('user_id',user.id).maybeSingle();role=r.data?.role||'viewer';permissions=r.data?.permissions||{}}await refresh()}
$('#search').onsubmit=e=>{e.preventDefault();location.hash='search/'+encodeURIComponent(e.target.querySelector('input').value)};$('#close-dialog').onclick=()=>$('#dialog').close();window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
setupSearchSuggestions();setupImageObserver();await refresh();await render();if(configured){try{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.57.4');db=createClient(cfg.supabaseUrl,cfg.supabaseKey);await session();db.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY')location.hash='reset'});await render();setInterval(async()=>{if(!['control','account','episode','live','article'].includes(location.hash.slice(1).split('/')[0])&&!document.querySelector('dialog[open]')&&!document.querySelector('#search:focus-within')){await refresh();await render()}},60000)}catch(e){notify('The content service is unavailable. '+e.message)}}
